{
  "story": "Bayesian optimization builds a probabilistic surrogate model from evaluated points. It then uses an acquisition function to balance exploring uncertain regions and exploiting known high performers, picking the next sample where utility peaks.",
  "aha": {
    "stateId": "acq",
    "observation": "The acquisition function peaks at an unexplored region with high model uncertainty, directing the next test."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "variant.states.active",
        "regions": "variant.regions",
        "completedBefore": "inputs.stepIndex"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readouts",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": [
        "Surrogate",
        "Uncertainty",
        "Acquisition",
        "Sample"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Bayesian Loop",
        "regions": [
          {
            "id": "regModel",
            "label": "Surrogate Model",
            "values": ["Fit GP", "Mean & Var"]
          },
          {
            "id": "regAcq",
            "label": "Acquisition Function",
            "values": ["Calculate EI", "Find Maximum"]
          }
        ],
        "links": [
          {
            "from": "regModel",
            "to": "regAcq",
            "label": "posterior"
          }
        ],
        "states": [
          {
            "id": "surr",
            "label": "Fit Surrogate",
            "short": "Model",
            "sentence": "A Gaussian Process fits the observed evaluations.",
            "why": "Provides a smooth probabilistic estimate across the whole space.",
            "active": ["regModel"],
            "calloutRegion": "regModel",
            "readouts": [
              {
                "id": "r1",
                "label": "Points evaluated",
                "value": "4"
              }
            ]
          },
          {
            "id": "unc",
            "label": "Estimate Variance",
            "short": "Uncertainty",
            "sentence": "Model uncertainty remains high far from tested points.",
            "why": "Quantifies ignorance to guide safe exploration.",
            "active": ["regModel"],
            "calloutRegion": "regModel",
            "readouts": [
              {
                "id": "r2",
                "label": "Max uncertainty",
                "value": "0.82"
              }
            ]
          },
          {
            "id": "acq",
            "label": "Compute Acquisition",
            "short": "Acquisition",
            "sentence": "Expected Improvement combines predicted mean and variance.",
            "why": "Balances exploitation of good areas with exploration of unknowns.",
            "active": ["regAcq"],
            "calloutRegion": "regAcq",
            "readouts": [
              {
                "id": "r3",
                "label": "Peak EI score",
                "value": "1.45"
              }
            ]
          },
          {
            "id": "sample",
            "label": "Select Next",
            "short": "Sample",
            "sentence": "The peak of the acquisition function determines the next setting.",
            "why": "Maximizes expected gain per physical experiment.",
            "active": ["regAcq"],
            "calloutRegion": "regAcq",
            "readouts": [
              {
                "id": "r4",
                "label": "Next X",
                "value": "0.74"
              }
            ]
          }
        ]
      }
    ]
  }
}
